{"results": [{"id": "hp_doc_6d7bfd63c23f75074f97885e0a1267b9176fb2a5b9cf159ceb4457c9f0e4d7b8", "title": "Cry, Onion!", "text": "Cry, Onion! (Italian: \"Cipolla Colt\" , lit. \"Onion Colt\", also known as \"The Smell of Onion\") is a 1975 Spaghetti Western comedy film directed by Enzo G. Castellari. It is openly comedic and parodic.", "score": 43.7475}, {"id": "hp_doc_939c228253f3308a4b13b96eef069b73524e6cd04b5aeb3bdbf7fb48f1eb07e7", "title": "Striker (1987 film)", "text": "Striker (also known as Combat Force) is a 1987 Italian war-action film directed by Enzo G. Castellari. The film reprises the style of the \"\"Rambo\"\" movies.", "score": 17.4174}, {"id": "hp_doc_28cb072b9e99f3a768071aefd1bd177df299a4c0e627458821b9e39d2de10234", "title": "The House by the Edge of the Lake", "text": "Sensitività (internationally released as The House by the Edge of the Lake, also known as \"Diabla\") is a 1979 Italian horror film directed by Enzo G. Castellari. The film was re-edited ten years after with the title \"Kyra, La signora del lago\" (\"Kyra, the Lady of the Lake\"). The director Castellari defined that film as an \"awful horror film with a very low cost budget\".", "score": 15.9579}], "remaining_searches": 2}
